#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <mutex>
#include <thread>
#include <atomic>
#include <signal.h>
#include <algorithm>
#include <sstream>
#include <functional>
#include <regex>
#include <random>
#include <chrono>

static std::atomic<bool> g_shutdown_requested{false};
static std::mutex g_index_mutex;

void signal_handler(int sig) {
    g_shutdown_requested.store(true);
}

struct OAuthConfig {
    std::string client_id;
    std::string client_secret;
    std::vector<std::string> allowed_redirect_uris;
    std::string authorization_endpoint;
};

struct SearchIndex {
    std::map<std::string, std::vector<int>> inverted_index;
    std::vector<std::string> documents;
    std::atomic<int> pending_ops{0};
};

class RedirectValidator {
public:
    RedirectValidator(const std::vector<std::string>& allowed_uris)
        : allowed_uris_(allowed_uris) {}

    bool is_valid_redirect(const std::string& redirect_uri) const {
        std::string normalized = normalize_uri(redirect_uri);

        // Exact match against pre-registered redirect URIs only
        for (const auto& allowed : allowed_uris_) {
            std::string normalized_allowed = normalize_uri(allowed);
            if (normalized == normalized_allowed) {
                return true;
            }
        }
        return false;
    }

private:
    std::string normalize_uri(const std::string& uri) const {
        std::string result = uri;
        // Only normalize scheme and host case (RFC 3986 section 6.2.2.1)
        size_t scheme_end = result.find("://");
        if (scheme_end == std::string::npos) return "";

        // Validate scheme is https
        std::string scheme = result.substr(0, scheme_end);
        std::transform(scheme.begin(), scheme.end(), scheme.begin(), ::tolower);
        if (scheme != "https") return "";

        size_t host_start = scheme_end + 3;

        // Reject URIs with userinfo component (RFC 3986 section 3.2.1)
        size_t slash_pos = result.find('/', host_start);
        size_t at_pos = result.find('@', host_start);
        if (at_pos != std::string::npos && (slash_pos == std::string::npos || at_pos < slash_pos)) {
            return "";  // Reject userinfo in redirect URIs
        }

        // Reject URIs with fragments
        if (result.find('#') != std::string::npos) return "";

        size_t host_end = result.find_first_of(":/?#", host_start);
        if (host_end == std::string::npos) host_end = result.size();

        std::string host = result.substr(host_start, host_end - host_start);
        std::transform(host.begin(), host.end(), host.begin(), ::tolower);

        // Reconstruct with normalized scheme and host
        return "https://" + host + result.substr(host_end);
    }

    std::vector<std::string> allowed_uris_;
};

class SearchIndexService {
public:
    SearchIndexService(const OAuthConfig& config)
        : oauth_config_(config),
          validator_(config.allowed_redirect_uris) {}

    std::string handle_oauth_authorize(const std::map<std::string, std::string>& params) {
        auto redirect_it = params.find("redirect_uri");
        auto client_id_it = params.find("client_id");
        auto state_it = params.find("state");

        if (redirect_it == params.end() || client_id_it == params.end()) {
            return "error=invalid_request";
        }

        if (client_id_it->second != oauth_config_.client_id) {
            return "error=unauthorized_client";
        }

        if (!validator_.is_valid_redirect(redirect_it->second)) {
            return "error=invalid_redirect_uri";
        }

        // Generate authorization code and redirect
        std::string auth_code = generate_auth_code();
        std::string redirect_target = redirect_it->second + "?code=" + auth_code;
        if (state_it != params.end()) {
            redirect_target += "&state=" + state_it->second;
        }
        return "redirect:" + redirect_target;
    }

    void index_document(const std::string& doc) {
        if (g_shutdown_requested.load()) return;

        index_.pending_ops.fetch_add(1);
        std::lock_guard<std::mutex> lock(g_index_mutex);

        int doc_id = index_.documents.size();
        index_.documents.push_back(doc);

        std::istringstream iss(doc);
        std::string word;
        while (iss >> word) {
            std::transform(word.begin(), word.end(), word.begin(), ::tolower);
            index_.inverted_index[word].push_back(doc_id);
        }
        index_.pending_ops.fetch_sub(1);
    }

    std::vector<std::string> search(const std::string& query) {
        std::lock_guard<std::mutex> lock(g_index_mutex);
        std::vector<std::string> results;

        std::string lower_query = query;
        std::transform(lower_query.begin(), lower_query.end(), lower_query.begin(), ::tolower);

        auto it = index_.inverted_index.find(lower_query);
        if (it != index_.inverted_index.end()) {
            for (int doc_id : it->second) {
                results.push_back(index_.documents[doc_id]);
            }
        }
        return results;
    }

    void graceful_shutdown() {
        g_shutdown_requested.store(true);
        // Wait for pending operations
        while (index_.pending_ops.load() > 0) {
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

private:
    std::string generate_auth_code() {
        // Use a cryptographically strong random source for unpredictable
        // authorization codes (CWE-330 fix).
        std::random_device rd;
        std::uniform_int_distribution<int> dist(0, 15);
        static const char hex[] = "0123456789abcdef";
        std::string code = "authcode_";
        // 256 bits of entropy (64 hex chars)
        for (int i = 0; i < 64; ++i) {
            code += hex[dist(rd)];
        }
        return code;
    }

    OAuthConfig oauth_config_;
    RedirectValidator validator_;
    SearchIndex index_;
};

int main() {
    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);

    OAuthConfig config;
    config.client_id = "search-indexer-client";
    config.client_secret = "secret123";
    config.allowed_redirect_uris = {"https://app.example.com/callback", "https://dashboard.example.com/callback"};
    config.authorization_endpoint = "/oauth/authorize";

    SearchIndexService service(config);

    // Simulate indexing
    service.index_document("The quick brown fox jumps over the lazy dog");
    service.index_document("Search indexing service handles OAuth tokens");

    // Simulate OAuth request
    std::map<std::string, std::string> params;
    params["client_id"] = "search-indexer-client";
    params["redirect_uri"] = "https://app.example.com/callback";
    params["state"] = "random_state_value";

    std::string result = service.handle_oauth_authorize(params);
    std::cout << "OAuth result: " << result << std::endl;

    auto search_results = service.search("oauth");
    std::cout << "Search results: " << search_results.size() << std::endl;

    if (g_shutdown_requested.load()) {
        service.graceful_shutdown();
    }

    return 0;
}
